import React, { useState, useEffect } from "react";
import Layout from "../../components/Layout";
import { useParams } from "react-router-dom";
import { Col, Form, Input, Row, TimePicker, message } from "antd";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { showLoading, hideLoading } from "../../redux/features/alertSlice";
import moment from "moment";

const Profile = () => {
  const [doctor, setDoctor] = useState(null);
  const { user } = useSelector((state) => state.user);
  const params = useParams();
  const dispatch = useDispatch();
  const navigate = useNavigate();

  //Update Doctor Profile
  const handleFinish = async (values) => {
    // console.log(values);
    try {
      dispatch(showLoading());

       // Format timings before sending to backend
    const formattedTimings = values.timings.map(time =>
      time.format("HH:mm")
    );
    // console.log(formattedTimings, 'formattedTimings');

      const res = await axios.post(
        "/api/v1/doctor/updateProfile",
        {
          ...values,
          userId: user._id,
          timings: formattedTimings,
          // timings: [
          //   moment(values.timings[0], "HH:mm"),
          //   moment(values.timings[1], "HH:mm"),
          // ],
        },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );
      dispatch(hideLoading());
      if (res.data.success) {
        message.success(res.data.message);
        navigate("/");
      } else {
        message.error(res.data.success);
      }
    } catch (error) {
      dispatch(hideLoading());
      console.log(error);
      message.error("Something went wrong");
    }
  };

  //get Doc Detail
  const getDoctorInfo = async () => {
    try {
      const res = await axios.post(
        "/api/v1/doctor/getDoctorInfo",
        { userId: params.id },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );
      if (res.data.data) {
        // Convert timings to Date objects
        const doctorData = res.data.data;
        if (doctorData.timings && doctorData.timings.length === 2) {
          doctorData.timings = [
            // moment(doctorData.timings[0]).format("YYYY-MM-DD HH:mm"),
            // moment(doctorData.timings[1]).format("YYYY-MM-DD HH:mm"),
            moment(`2000-01-01 ${doctorData.timings[0]}`, "YYYY-MM-DD HH:mm"),
            moment(`2000-01-01 ${doctorData.timings[1]}`, "YYYY-MM-DD HH:mm"),
          ];
        }
        setDoctor(res.data.data);
      }
    } catch (error) {
      console.log(error);
      // message.error('Something Went Wrong')
    }
  };

  useEffect(() => {
    getDoctorInfo();
  }, []);
  return (
    <Layout>
      <h1> Manage Profile </h1>
      {doctor && (
        <Form
          layout="vertical"
          onFinish={handleFinish}
          className="m-3"
          // initialValues={doctor}
          initialValues={{
            ...doctor,
            timings: [
              moment(doctor.timings[0], "HH:mm"),
              moment(doctor.timings[1], "HH:mm"),
              // moment(doctor.timings[0]).format("HH:mm"),
              // moment(doctor.timings[1]).format("HH:mm"),
            ],
          }}
        >
          <h4 className="">Personal Details:</h4>
          <Row gutter={20}>
            <Col xs={24} md={24} lg={8}>
              <Form.Item
                label="First Name"
                name="firstName"
                required
                rules={[{ required: true }]}
              >
                <Input type="text" placeholder="your first name" />
              </Form.Item>
            </Col>
            <Col xs={24} md={24} lg={8}>
              <Form.Item
                label="Last Name"
                name="lastName"
                required
                rules={[{ required: true }]}
              >
                <Input type="text" placeholder="your last name" />
              </Form.Item>
            </Col>
            <Col xs={24} md={24} lg={8}>
              <Form.Item
                label="Phone Number"
                name="phoneNumber"
                required
                rules={[{ required: true }]}
              >
                <Input type="number" placeholder="your phone number" />
              </Form.Item>
            </Col>
            <Col xs={24} md={24} lg={8}>
              <Form.Item
                label="Email"
                name="email"
                required
                rules={[{ required: true }]}
              >
                <Input type="email" placeholder="your email" />
              </Form.Item>
            </Col>{" "}
            <Col xs={24} md={24} lg={8}>
              <Form.Item label="Website" name="website">
                <Input type="text" placeholder="your website" />
              </Form.Item>
            </Col>{" "}
            <Col xs={24} md={24} lg={8}>
              <Form.Item
                label="Address"
                name="address"
                required
                rules={[{ required: true }]}
              >
                <Input type="text" placeholder="your clinic address" />
              </Form.Item>
            </Col>
          </Row>

          <h4 className="">Professional Details:</h4>
          <Row gutter={20}>
            <Col xs={24} md={24} lg={8}>
              <Form.Item
                label="Specialization"
                name="specialization"
                required
                rules={[{ required: true }]}
              >
                <Input type="text" placeholder="your specialization" />
              </Form.Item>
            </Col>
            <Col xs={24} md={24} lg={8}>
              <Form.Item
                label="Experience"
                name="experience"
                required
                rules={[{ required: true }]}
              >
                <Input type="text" placeholder="your experience" />
              </Form.Item>
            </Col>
            <Col xs={24} md={24} lg={8}>
              <Form.Item
                label="Fees Per Consultation"
                name="feesPerConsultation"
                required
                rules={[{ required: true }]}
              >
                <Input type="text" placeholder="your consultation fee" />
              </Form.Item>
            </Col>

            <Col xs={24} md={24} lg={8}>
              <Form.Item label="Timings" name="timings" required>
                <TimePicker.RangePicker format="HH : mm" />
              </Form.Item>
            </Col>

            <Col xs={24} md={24} lg={8}></Col>
            <Col xs={24} md={24} lg={8}>
              <button className="btn btn-primary form-btn" type="submit">
                Update
              </button>
            </Col>
          </Row>
          {/* <div className="d-flex justify-content-end mb-3">
          
        </div> */}
        </Form>
      )}
    </Layout>
  );
};

export default Profile;
