import React, { useState, useEffect } from "react";
import Layout from "../../components/Layout";
import axios from "axios";
import { Table, Spin, message } from "antd";

const Doctors = () => {
  const [doctors, setDoctors] = useState([]);
  const [loading, setLoading] = useState(true);
  // const [loadings, setLoadings] = useState([]);

  const getDoctors = async () => {
    try {
      const res = await axios.get("/api/v1/admin/getAllDoctors", {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      });
      if (res.data.success) {
        setDoctors(res.data.data);
      }
    } catch (error) {
      console.log(error);
    } finally {
      setLoading(false); // Set loading to false after data is fetched (success or error)
    }
  };

  //handleAccountStatus
  // const handleAccountStatus = async (record, status) => {
  //   try {
  //     const res = await axios.post(
  //       "/api/v1/admin/getAccountStatus",
  //       { doctorId: record._id, userId: record.userId, status: status },
  //       {
  //         headers: {
  //           Authorization: `Bearer ${localStorage.getItem("token")}`,
  //         },
  //       }
  //     );
  //     if (res.data.success) {
  //       message.success(res.data.message);
  //       window.location.reload();
  //     }
  //   } catch (error) {
  //     message.error("Something Went Wrong");
  //   }
  // };
  const handleAccountStatus = async (record, status) => {
    try {
      const res = await axios.post(
        "/api/v1/admin/getAccountStatus",
        { doctorId: record._id, userId: record.userId, status: status },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );
      if (res.data.success) {
        message.success(res.data.message);
        // Update the status of the doctor in the state
        setDoctors((prevDoctors) => {
          const updatedDoctors = prevDoctors.map((doctor) =>
            doctor._id === record._id ? { ...doctor, status: status } : doctor
          );
          return updatedDoctors;
        });
      }
    } catch (error) {
      message.error("Something Went Wrong");
    }
  };

  useEffect(() => {
    getDoctors();
  }, []);

  const columns = [
    {
      title: "Name",
      dataIndex: "name",
      render: (text, record) => (
        <span>
          {record.firstName} {record.lastName}{" "}
        </span>
      ),
    },
    {
      title: "Specialization",
      dataIndex: "specialization",
    },
    {
      title: "Experience",
      dataIndex: "experience",
    },
    {
      title: "Consultation Fee",
      dataIndex: "feesPerConsultation",
    },
    {
      title: "Status",
      dataIndex: "status",
    },
    {
      title: "Phone",
      dataIndex: "phoneNumber",
    },
    {
      title: "Actions",
      dataIndex: "actions",
      render: (text, record) => (
        <div className="d-flex">
          {record.status === "pending" ? (
            <button
              className="btn btn-success"
              onClick={() => handleAccountStatus(record, "approved")}
            >
              Approve
            </button>
          ) : (
            <button className="btn btn-danger">Reject</button>
          )}
        </div>
      ),
    },
  ];
  return (
    <Layout>
      <h1 className="text-center m-2">Doctors List</h1>
      <Spin spinning={loading}>
        {/* <Table columns={columns} dataSource={doctors} /> */}
        <Table
          columns={columns}
          dataSource={doctors.map((doctor) => ({ ...doctor, key: doctor._id }))}
        />
      </Spin>
    </Layout>
  );
};

export default Doctors;
