import Layout from "../components/Layout";
import React, { useState } from "react";
import { Tabs, message } from "antd";
import { useSelector, useDispatch } from "react-redux";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import {
  showLoading,
  hideLoading,
} from "../redux/features/alertSlice";

const NotificationPage = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { user } = useSelector((state) => state.user);

  const [unreadNotifications, setUnreadNotifications] = useState(user?.notification || []);
  const [readNotifications, setReadNotifications] = useState(user?.seennotification || []);

  const handleMarkAllRead = async () => {
    try {
      dispatch(showLoading());
      const res = await axios.post(
        "/api/v1/user/get-all-notifications",
        {
          userId: user._id,
        },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );
      dispatch(hideLoading());
      if (res.data.success) {
        message.success(res.data.message);
        setUnreadNotifications([]);
      } else {
        message.error(res.data.message);
      }
    } catch (error) {
      dispatch(hideLoading());
      console.log(error);
      message.error("Something went wrong");
    }
  };

  const handleDeleteAllRead = async () => {
    try {
      dispatch(showLoading());
      const res = await axios.post(
        "/api/v1/user/delete-all-notifications",
        { userId: user._id },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );
      dispatch(hideLoading());
      if (res.data.success) {
        message.success(res.data.message);
        setReadNotifications([]);
      } else {
        message.error(res.data.message);
      }
    } catch (error) {
      dispatch(hideLoading());
      console.log(error);
      message.error("Something Went Wrong in Notifications");
    }
  };

  return (
    <Layout>
      <h4 className="p-3 text-center"> NOTIFICATION PAGE </h4>
      <Tabs>
        <Tabs.TabPane tab="Unread" key={0}>
          <div className="d-flex justify-content-end" style={{ cursor: "pointer" }}>
            <h4 className="p-2" onClick={handleMarkAllRead}>
              Mark All Read
            </h4>
          </div>
          {unreadNotifications.map((notiMess) => (
            <div key={notiMess.message} className="card" style={{ cursor: "pointer" }}>
              <div className="card-text" onClick={() => navigate(notiMess.onClickPath)}>
                {notiMess.message}
              </div>
            </div>
          ))}
        </Tabs.TabPane>
        <Tabs.TabPane tab="Read" key={1}>
          <div className="d-flex justify-content-end">
            <h4 className="p-2 text-primary" style={{ cursor: "pointer" }} onClick={handleDeleteAllRead}>
              Delete All Read
            </h4>
          </div>
          {readNotifications.map((notiMess) => (
            <div key={notiMess.message} className="card" style={{ cursor: "pointer" }}>
              <div className="card-text" onClick={() => navigate(notiMess.onClickPath)}>
                {notiMess.message}
              </div>
            </div>
          ))}
        </Tabs.TabPane>
      </Tabs>
    </Layout>
  );
};

export default NotificationPage;


